export class PeopleList {
  protected readonly people = inject(People);
  protected readonly claims = inject(Claims);
  private readonly figures = inject(Figures);
  protected readonly grades = GRADES;
  /** The people the list shows: everyone, or only those not retired unless show retired is on. */
  protected readonly shown = computed(() =>
    this.people.showRetired() ? this.people.people() : this.people.people().filter((p) => !p.retired),
  );
  /** The retire-from date typed on each person's row. */
  protected readonly retireDates = signal<Record<number, string>>({});
  /** The id of the person being retired. */
  protected readonly retiring = signal<number | null>(null);
  /** The id of the person being put on or taken off hold. */
  protected readonly holding = signal<number | null>(null);
  /** Everyone's due-total added up, skipping those whose grade has no rate. */
  protected readonly dueTotal = computed(() =>
    money(this.people.people().reduce((sum, p) => sum + (this.dueCents(p) ?? 0n), 0n)),
  );
  /** Everyone's overdue claims that count, counted. */
  protected readonly overdueCount = computed(() =>
    this.people.people().reduce((n, p) => n + this.overdue(p).length, 0),
  );
  /** The due of everyone's overdue claims that count, added up. */
  protected readonly overdueTotal = computed(() =>
    money(this.people.people().reduce((sum, p) => sum + this.overdueCents(p), 0n)),
  );
  protected readonly name = signal('');
  protected readonly grade = signal<string>('A');
  /** The date the editor's grade applies from; blank takes the sheet's today. */
  protected readonly gradeFrom = signal('');
  /** The id of the person whose editor is open, or null when the form adds. */
  protected readonly editing = signal<number | null>(null);
  /** The version of the person the editor loaded; a save from it is refused once someone else saved. */
  private readonly version = signal(0);
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  protected readonly quickName = signal('');
  protected readonly quickAmount = signal('');
  protected readonly quickError = signal<string | null>(null);
  protected readonly quickSaving = signal(false);
  /** The id of the person whose statement is being taken. */
  protected readonly stating = signal<number | null>(null);
  /** The patron chosen on each person's row (a person id), blank while none is. */
  protected readonly patronChoices = signal<Record<number, string>>({});
  /** The id of the person a patron is being added to. */
  protected readonly addingPatron = signal<number | null>(null);
  /** The last refused patron added to a person, shown on their row until the next action on it. */
  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
  /** The last refused action on a person, shown on their row until the next action on it. */
  protected readonly actionError = signal<{ id: number; message: string } | null>(null);

  protected checked(e: Event): boolean {
    return (e.target as HTMLInputElement).checked;
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement | HTMLSelectElement).value;
  }

  private dueCents(p: Person): bigint | null {
    return this.figures.dueCents(p);
  }

  private figureCents(c: Claim, p: Person): bigint {
    return this.figures.figureCents(c, p);
  }

  /** The grade in force on the sheet's today, the one the list shows. */
  protected gradeToday(p: Person): string {
    return this.figures.gradeToday(p);
  }

  /** A person's claims that count live and are overdue. */
  protected overdue(p: Person): Claim[] {
    return this.claims.live().filter((c) => c.personId === p.id && this.claims.overdue(c));
  }

  /** The due of a person's overdue claims that count, added up. */
  private overdueCents(p: Person): bigint {
    return this.overdue(p).reduce((sum, c) => sum + this.figureCents(c, p), 0n);
  }

  protected overdueDue(p: Person): string {
    return money(this.overdueCents(p));
  }

  /** The people a person may choose among as a patron: everyone else on the sheet. */
  protected others(p: Person): Person[] {
    return this.people.people().filter((o) => o.id !== p.id);
  }

  private patronsOf(p: Person): Person[] {
    const ids = new Set(p.patronIds);
    return this.people.people().filter((o) => ids.has(o.id));
  }

  /** A person's patrons' names, sorted, comma and space separated. */
  protected patrons(p: Person): string {
    return this.patronsOf(p).map((o) => o.name).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)).join(', ');
  }

  /** A person's patrons' due-totals added up, skipping those that are n/a; 0.00 with no patrons. */
  protected backing(p: Person): string {
    return money(this.patronsOf(p).reduce((sum, o) => sum + (this.dueCents(o) ?? 0n), 0n));
  }

  protected setPatronChoice(id: number, choice: string): void {
    this.clearActionError(id);
    this.patronChoices.update((cs) => ({ ...cs, [id]: choice }));
  }

  protected async addPatron(p: Person): Promise<void> {
    this.clearActionError(p.id);
    const choice = this.patronChoices()[p.id] ?? '';
    if (!choice) {
      this.patronError.set({ id: p.id, message: 'Choose a patron.' });
      return;
    }
    this.addingPatron.set(p.id);
    try {
      const err = await this.people.addPatron(p.id, Number(choice));
      if (err) this.patronError.set({ id: p.id, message: err });
      else this.patronChoices.update((cs) => ({ ...cs, [p.id]: '' }));
    } finally {
      this.addingPatron.set(null);
    }
  }

  protected due(p: Person): string {
    const d = this.dueCents(p);
    return d === null ? NO_RATE : money(d);
  }

  protected async statement(p: Person): Promise<void> {
    this.clearActionError(p.id);
    this.stating.set(p.id);
    try {
      const stated = await this.people.statement(p.id);
      if (typeof stated === 'string') this.actionError.set({ id: p.id, message: stated });
      else this.claims.replaceOf(p.id, stated.claims);
    } finally {
      this.stating.set(null);
    }
  }

  protected setRetireDate(id: number, date: string): void {
    this.clearActionError(id);
    this.retireDates.update((ds) => ({ ...ds, [id]: date }));
  }

  protected async retire(p: Person): Promise<void> {
    this.clearActionError(p.id);
    this.retiring.set(p.id);
    try {
      const err = await this.people.retire(p.id, this.retireDates()[p.id] ?? '');
      if (err) this.actionError.set({ id: p.id, message: err });
    } finally {
      this.retiring.set(null);
    }
  }

  protected async toggleHold(p: Person): Promise<void> {
    this.clearActionError(p.id);
    this.holding.set(p.id);
    try {
      const err = await this.people.toggleHold(p.id);
      if (err) this.actionError.set({ id: p.id, message: err });
    } finally {
      this.holding.set(null);
    }
  }

  private clearActionError(id: number): void {
    if (this.actionError()?.id === id) this.actionError.set(null);
    if (this.patronError()?.id === id) this.patronError.set(null);
  }

  protected edit(p: Person): void {
    this.clearActionError(p.id);
    this.editing.set(p.id);
    this.load(p);
    this.error.set(null);
  }

  private load(p: Person): void {
    this.version.set(p.version);
    this.name.set(p.name);
    this.grade.set(this.gradeToday(p));
    this.gradeFrom.set('');
  }

  protected reset(): void {
    this.editing.set(null);
    this.name.set('');
    this.grade.set('A');
    this.gradeFrom.set('');
    this.error.set(null);
  }

  protected async quickAdd(e: Event): Promise<void> {
    e.preventDefault();
    if (this.quickSaving()) return; // a second submit before the first has answered
    this.quickError.set(null);
    this.quickSaving.set(true);
    try {
      const err = await this.claims.quickAdd(this.quickName(), this.quickAmount());
      if (err) this.quickError.set(err);
      else {
        this.quickName.set('');
        this.quickAmount.set('');
      }
    } finally {
      this.quickSaving.set(false);
    }
  }

  protected async submit(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
    try {
      const f = { name: this.name(), grade: this.grade(), gradeFrom: this.gradeFrom() };
      const id = this.editing();
      if (id === null) {
        const err = await this.people.add(f);
        if (err) this.error.set(err);
        else this.reset();
      } else {
        const refusal = await this.people.update(id, this.version(), f);
        if (!refusal) this.reset();
        else {
          if (refusal.current) this.load(refusal.current);
          this.error.set(refusal.error);
        }
      }
    } finally {
      this.saving.set(false);
    }
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Claim } from './claims';
import { Session } from './session';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade a person was given, from a date (YYYY-MM-DD); null for the first, from the beginning of time. */
export interface GradeFrom {
  grade: string;
  from: string | null;
}

/** The grade in force on a date (YYYY-MM-DD): the one whose from-date is the latest on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): string {
  let found: string | undefined;
  for (const g of grades) {
    if (found === undefined || g.from === null || g.from <= date) found = g.grade;
  }
  return found ?? '';
}

export interface Person {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the server answered. */
  grade: string;
  /** Every grade they were given, the first (no from-date) first, then by from-date. */
  grades: GradeFrom[];
  /** Moved on by each save; an edit made from an older version is refused. */
  version: number;
  /** How many statements were taken of them. */
  statementCount: number;
  /** The last statement's due-total, two decimals or n/a; null before their first. */
  statedTotal: string | null;
  /** The sheet's today when the last statement was taken; null before their first. */
  statementDate: string | null;
  /** Whether a retirement date is set: then they count as retired at once, whatever the date. */
  retired: boolean;
  /** The date they are retired from (YYYY-MM-DD); null while not retired. */
  retiredFrom: string | null;
  /** On hold: their OPEN claims count in no live total; their SETTLED ones still do. */
  held: boolean;
  /** The ids of the other people on the sheet they have named as their patrons. */
  patronIds: number[];
}

/** A person after a statement, with their claims as it bound them, newest first. */
export interface Statement {
  person: Person;
  claims: Claim[];
}

/** A refused save: why, and the person as stored now when someone else saved them first. */
export interface Refusal {
  error: string;
  current?: Person;
}

export interface PersonFields {
  name: string;
  grade: string;
  /** The date an edit's grade applies from (YYYY-MM-DD); blank takes the sheet's today. */
  gradeFrom?: string;
}

// The people on the active sheet, in the order they were added, re-read from the server each
// time the sheet is loaded.
@Injectable({ providedIn: 'root' })
export class People {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly people = signal<Person[]>([]);
  /** Whether the list shows retired people; belongs to the screen, so loading a sheet leaves it. */
  readonly showRetired = signal(false);
  private loads = 0;

  /** Re-read the active sheet's people from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.people.set([]);
    if (!user || !sid) return null;
    try {
      const people = await firstValueFrom(
        this.http.get<Person[]>(this.url(sid), { headers: { 'X-User': user } }),
      );
      if (load === this.loads) this.people.set(people);
      return null;
    } catch (e) {
      return failed('load', e).replace(' person', ' people');
    }
  }

  /** Add a person; an error message when refused. */
  async add(f: PersonFields): Promise<string | null> {
    const refused = this.check(f);
    if (refused) return refused;
    const sid = this.session.sheetId()!;
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(this.url(sid), this.body(f), { headers: { 'X-User': this.session.user()! } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => [...ps, person]);
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Change a person's name and grade, from the version the editor loaded; the refusal when
   *  refused, carrying the person as stored now when someone else saved them in the meantime. */
  async update(id: number, version: number, f: PersonFields): Promise<Refusal | null> {
    const refused = this.check(f);
    if (refused) return { error: refused };
    const sid = this.session.sheetId()!;
    const put = (person: Person) => {
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
    };
    try {
      put(
        await firstValueFrom(
          this.http.put<Person>(`${this.url(sid)}/${id}`, { ...this.body(f), gradeFrom: f.gradeFrom?.trim() || null, version }, {
            headers: { 'X-User': this.session.user()! },
          }),
        ),
      );
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 412) {
        const current = e.error as Person;
        put(current);
        return { error: 'Someone else has changed this person. Their values are shown; review and save again.', current };
      }
      return { error: failed('save', e) };
    }
  }

  /** Take a person's statement: the person and their claims as it left them, or an error message
   *  when refused. */
  async statement(id: number): Promise<Statement | string> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const stated = await firstValueFrom(
        this.http.post<Statement>(`${this.url(sid)}/${id}/statement`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) {
        this.people.update((ps) => ps.map((p) => (p.id === id ? stated.person : p)));
      }
      return stated;
    } catch (e) {
      return failed('take statement of', e);
    }
  }

  /** Retire a person from a date (blank takes the sheet's today); an error message when refused. */
  async retire(id: number, from: string): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    const d = from.trim();
    if (d && !/^\d{4}-\d{2}-\d{2}$/.test(d)) return 'Enter a date as YYYY-MM-DD.';
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(`${this.url(sid)}/${id}/retire`, { from: d || null }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
      return null;
    } catch (e) {
      return failed('retire', e);
    }
  }

  /** Put a person on hold, or take them off it; an error message when refused. */
  async toggleHold(id: number): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(`${this.url(sid)}/${id}/hold`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
      return null;
    } catch (e) {
      return failed('hold', e);
    }
  }

  /** Name another person on the sheet as a person's patron; an error message when refused. */
  async addPatron(id: number, patronId: number): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    if (patronId === id) return 'A person cannot be their own patron.';
    try {
      const person = await firstValueFrom(
        this.http.post<Person>(`${this.url(sid)}/${id}/patrons`, { patronId }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.people.update((ps) => ps.map((p) => (p.id === id ? person : p)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) {
        const err: unknown = e.error;
        if (err && typeof err === 'object' && 'message' in err && typeof err.message === 'string') return err.message;
      }
      return failed('add patron to', e);
    }
  }

  private check(f: PersonFields): string | null {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!f.name.trim()) return 'Enter a name.';
    if (!(GRADES as readonly string[]).includes(f.grade)) return 'Choose a grade.';
    const from = f.gradeFrom?.trim();
    if (from && !/^\d{4}-\d{2}-\d{2}$/.test(from)) return 'Enter the grade\'s from-date as YYYY-MM-DD.';
    return null;
  }

  private body(f: PersonFields): PersonFields {
    return { name: f.name.trim(), grade: f.grade };
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/people`;
  }
}

function failed(what: string, e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That name is already in use.';
  return e instanceof HttpErrorResponse ? `Could not ${what} person (${e.status}).` : `Could not ${what} person.`;
}

